; Player and joystick digits of the title
; $8588-$85a6

; When the options show, writes the number of players and of joysticks as two map cells each.
show_player_options
        lda options_hidden              ; OPTION in the developer symbol table of the Micro Fun build.
        bne show_player_options_done
        lda two_players                 ; Digit 1 is $11. The right half of a character is the code plus $34.
        clc
        adc #$11
        sta title_player_digit
        adc #$34
        sta $0b71
        lda two_joysticks
        clc
        adc #$11
        sta $0b84
        adc #$34
        sta $0b85
show_player_options_done
        rts                             ; EXIT in the developer symbol table of the Micro Fun build.
